style.css:
@-moz-document domain("roblox.com") {
/* Set the background to the 3rd Rivals Champion artwork */
    body, 
    .content, 
    #container-main,
    .dark-theme,
    #wrap {
        background: url("https://ytimg.com") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Keep the panel text readable by applying a smooth dark overlay */
    .section-content,
    .container-header,
    .layer,
    .game-card-container,
    .item-card-container,
    .profile-header,
    .rbx-tab-content,
    .content-area {
        background-color: rgba(20, 20, 20, 0.75) !important;
        border-radius: 10px !important;
        border: 1px solid rgba(255, 215, 0, 0.15) !important; /* Subtle golden tint border to match the art */
    }

    /* Make the main page container float nicely above the artwork */
    #roblox-linkify, .js-page-container {
        background: rgba(0, 0, 0, 0.3) !important;
    }

    /* Style the top header bar to seamlessly blend with the deep background colours */
    #header {
        background-color: rgba(10, 10, 10, 0.9) !important;
    }
}
